// Adapter: the rule below is the same JavaScript as the recipe's n8n build.
// $('Step name') answers from this step's inputs: each is that step's output in this scenario.
const SOURCES = {"Config": "in0_Config", "Read drafts awaiting approval": "in1_Readdraftsawaitingapprov"};
const LISTS = [];
const EXECUTED = [];
const DATA = {};
for (const [node, key] of Object.entries(SOURCES)) {
  const raw = input[key];
  let v = raw;
  if (typeof raw === 'string') { try { v = JSON.parse(raw); } catch (e) { v = raw; } }
  DATA[node] = LISTS.includes(node) ? (v || []).map(i => (i && i.json !== undefined ? i : { json: i })) : [{ json: v }];
}
const $ = (node) => {
  const ran = node in DATA || EXECUTED.includes(node);
  const list = () => { if (!(node in DATA)) throw new Error(`step ${node} has no data in this scenario`); return DATA[node]; };
  return { isExecuted: ran, first: () => list()[0], last: () => list()[list().length - 1], all: () => list(),
           get item() { return list()[0]; } };
};
const INPUT = "Read drafts awaiting approval";
const $input = { all: () => $(INPUT).all(), first: () => $(INPUT).first(), last: () => $(INPUT).last(), get item() { return $(INPUT).first(); } };
const $execution = { id: input.run_id };
const BODIES = (out) => ({"message": out.count > 0 ? JSON.stringify({ to: $('Config').first().json.article_owner, subject: out.count + ' drafts waiting over ' + $('Config').first().json.old_draft_days + ' days', text: 'Approve or discard: ' + out.ids.join(', ') }) : null});
const one = (r) => (Array.isArray(r) ? r : [r]).filter(Boolean).map(i => (i.json !== undefined ? i.json : i));
const $json = INPUT && INPUT in DATA ? $input.first().json : {};
const __rule = () => {
// Failure table: a weekly count of drafts over 14 days old, for the article owner to clear.
const cfg = $('Config').first().json;
const cutoff = new Date(Date.now() - cfg.old_draft_days * 86400000).toISOString().slice(0, 10);
const old = ($('Read drafts awaiting approval').first().json.items || []).filter(d => String(d.created) < cutoff);
return [{ json: { count: old.length, ids: old.map(d => d.id) } }];
};
const out = one(__rule())[0] || {};
return Object.assign({}, out, BODIES(out));
